import {joinText, localizedNumber, msg, uiAttr, uiText} from './i18n.mjs';
export function createBookReader({manifest,load,normalize,matches,openView,copyText,toast}){
 const $=id=>document.getElementById(id),fa=n=>Number(n).toLocaleString('fa-IR');
 const cache=new Map();let book,booklet,volume,pages,index=0,request=0,searchRun=0,tocLimit=120;
 const positionKey='mansour-book-positions-v1';let positions={};try{positions=JSON.parse(localStorage.getItem(positionKey)||'{}')}catch{}
 function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)uiText(el, text);if(cls)el.className=cls;return el;}
 function option(value,text){const el=node('option',text);el.value=value;return el;}
 async function chunk(file){const url='full-books/'+volume.manifest.replace('manifest.json',file);if(cache.has(url))return cache.get(url);const response=await fetch(url);if(!response.ok)throw Error('فایل متن این جلد روی دستگاه موجود نیست. بستهٔ کتاب‌ها را از بخش «بسته‌های آفلاین» وارد کنید.');const values=await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json();if(cache.size>=6)cache.delete(cache.keys().next().value);cache.set(url,values);return values;}
 async function open(id,{volumeId,label,pageId,section,booklet:selection}={}){booklet=selection;book=manifest.books.find(b=>b.id===String(id));if(!book)return toast(msg("book-reader.book_text_unavailable_in_this_collection"));++searchRun;$('book-search-results').replaceChildren();$('book-search').value='';uiText($('book-title'), (booklet?.title || book.title));uiText($('book-author'), (book.author || ''));$('book-volume').replaceChildren(...book.volumes.map(v=>option(v.id,msg("book-reader.volume_0_1_pages", localizedNumber(Number(v.volume)||1), localizedNumber(v.pages)))));$('book-volume').disabled=!!booklet;const remembered=positions[booklet?.seriesId||book.id];const wanted=book.volumes.find(v=>v.id===volumeId||Number(v.volume)===Number(volumeId))||book.volumes.find(v=>v.id===remembered?.volume)||book.volumes[0];$('book-volume').value=wanted.id;openView('book');await loadVolume({label,pageId,section,position:volumeId||label||pageId?undefined:remembered?.index});}
 async function loadVolume({label,pageId,section,position}={}){const run=++request;++searchRun;volume=book.volumes.find(v=>v.id===$('book-volume').value);uiText($('book-page-text'), msg("book-reader.loading_volume"));const data=await load('full-books/'+volume.manifest);if(run!==request)return;pages=booklet?{...data,pages:data.pages.filter(p=>booklet.pageIds.includes(p.id)),toc:data.toc.filter(t=>booklet.pageIds.includes(t.pageId))}:data;index=Number.isInteger(position)?Math.max(0,Math.min(position,pages.pages.length-1)):0;if(pageId!=null){const p=pages.pages.findIndex(p=>(String(p.id)===String(pageId)||(p.sourcePageIds||[]).some(id=>String(id)===String(pageId))));if(p>=0)index=p;}else if(label!=null){const p=pages.pages.findIndex(p=>String(p.label)===String(label)&&(section==null||String(p.section)===String(section)));if(p>=0)index=p;}tocLimit=120;$('book-toc-search').value='';renderToc();await renderPage();}
 function renderToc(){const query=$('book-toc-search').value,rows=(pages.toc||[]).filter(t=>t.title&&matches(t.title,query));const frag=document.createDocumentFragment();for(const t of rows.slice(0,tocLimit)){const b=node('button',t.title);b.className='toc-item';b.style.paddingInlineStart=(10+Math.min(t.level||0,5)*10)+'px';b.disabled=t.pageId==null;b.onclick=()=>{const i=pages.pages.findIndex(p=>p.id===t.pageId&&(t.section==null||p.section===t.section));if(i>=0){index=i;renderPage().catch(e=>toast(e.message))}};frag.append(b);}$('book-toc').replaceChildren(frag);$('book-toc-more').hidden=rows.length<=tocLimit;}
 async function renderPage(){const run=++request,entry=pages.pages[index];if(!entry){uiText($('book-page-text'), msg("book-reader.no_pages_are_recorded_for_this_volume"));return;}$('book-prev').disabled=index===0;$('book-next').disabled=index===pages.pages.length-1;$('book-position').value=index+1;$('book-position').max=pages.pages.length;$('book-page-label').value=entry.label;uiText($('book-page-meta'), msg("book-reader.print_page_0_section_1_leaf_2", entry.label, entry.section??'—', localizedNumber(index+1), localizedNumber(pages.pages.length)));uiText($('book-page-text'), msg("book-reader.loading_page"));
 try{const rows=await chunk(entry.chunk);if(run!==request)return;const page=rows[entry.index];if(!page||String(page.id)!==String(entry.id))throw Error('شناسهٔ صفحه با فهرست کتاب سازگار نیست.');const fragment=document.createDocumentFragment();let hasText=false;for(const story of page.stories){if(!story.paragraphs.some(p=>String(p).trim())&&!story.images?.length)continue;hasText=true;const section=node('section',undefined,story.name==='Footnote'?'book-footnotes':'book-story');if(story.name==='Footnote')section.append(node('h3',msg("book-reader.footnote")));for(const p of story.paragraphs)section.append(node('p',p));for(const img of story.images||[]){if(img.missing){section.append(node('p',msg("book-reader.page_image_unavailable_in_source"),'empty'));continue;}const image=node('img');image.className='book-page-image';image.loading='lazy';uiAttr(image, "alt", (img.alt || msg("book-reader.source_page_image")));image.src='full-books/'+volume.manifest.replace('manifest.json',img.path);section.append(image);}fragment.append(section);}if(!hasText)fragment.append(node('p',msg("book-reader.no_indexed_text_on_this_page_it"),'empty'));$('book-page-text').replaceChildren(fragment);positions[booklet?.seriesId||book.id]={volume:volume.id,index};try{localStorage.setItem(positionKey,JSON.stringify(positions))}catch{}uiText($('book-citation'), msg("book-reader.0_1_2_vol_3_p_4", booklet?booklet.title+'، در: ':'', book.title, book.author||'', Number(volume.volume)||volume.volume, entry.label));}catch(e){if(run===request)$('book-page-text').replaceChildren(node('p',e.message,'empty'));}
 }
 async function search(){const query=$('book-search').value.trim();const run=++searchRun;$('book-search-results').replaceChildren();if(!query)return;const scope=volume.id,groups=[...new Set(pages.pages.map(p=>p.chunk))],results=[];for(let i=0;i<groups.length;i++){if(run!==searchRun||scope!==volume.id)return;uiText($('book-search-status'), msg("book-reader.searching_volume_section_0_of_1", localizedNumber(i+1), localizedNumber(groups.length)));const block=await chunk(groups[i]);for(const p of block){const text=p.stories.flatMap(s=>s.paragraphs).join('\n');if(matches(text,query))results.push({id:p.id,label:p.label,section:p.section,text:text.slice(0,260)});if(results.length>=100)break;}if(results.length>=100)break;await new Promise(r=>setTimeout(r,0));}if(run!==searchRun)return;uiText($('book-search-status'), (results.length>=100 ? msg("book-reader.first_100_results_narrow_your_search_for") : msg("book-reader.0_pages_in_this_volume", localizedNumber(results.length))));for(const result of results){const b=node('button',undefined,'search-item');b.append(node('strong',joinText(msg("book-reader.page"), " ", result.label)),node('p',result.text+'…'));b.onclick=()=>{index=pages.pages.findIndex(p=>p.id===result.id&&p.section===result.section&&String(p.label)===String(result.label));renderPage().catch(e=>toast(e.message));$('book-page-text').scrollIntoView({block:'start'})};$('book-search-results').append(b);}}
 $('book-volume').onchange=()=>loadVolume().catch(e=>toast(e.message));$('book-prev').onclick=()=>{if(index>0){index--;renderPage().catch(e=>toast(e.message))}};$('book-next').onclick=()=>{if(index<pages.pages.length-1){index++;renderPage().catch(e=>toast(e.message))}};
 $('book-position').onchange=()=>{const value=Number($('book-position').value);if(Number.isInteger(value)&&value>=1&&value<=pages.pages.length){index=value-1;renderPage().catch(e=>toast(e.message))}};
 $('book-go').onclick=()=>{const digits=s=>normalize(s).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632));const value=digits($('book-page-label').value),found=pages.pages.findIndex(p=>digits(String(p.label))===value);if(found<0)return toast(msg("book-reader.that_page_is_outside_the_current_volume"));index=found;renderPage().catch(e=>toast(e.message))};
 $('book-toc-search').oninput=()=>{tocLimit=120;renderToc()};$('book-toc-more').onclick=()=>{tocLimit+=120;renderToc()};$('book-search-form').onsubmit=e=>{e.preventDefault();search().catch(e=>{uiText($('book-search-status'), e.message)})};$('book-search-stop').onclick=()=>{++searchRun;uiText($('book-search-status'), msg("book-reader.search_stopped"))};
 $('book-copy').onclick=()=>copyText($('book-page-text').innerText+'\n'+$('book-citation').textContent).then(()=>toast(msg("book-reader.page_and_citation_copied"))).catch(()=>toast(msg("book-reader.copy_failed")));
 return {open};
}
